from PIL import Image
from collections import deque,Counter
im=Image.open('sheet.png'); W,H=im.size
a=im.getchannel('A').tobytes()
for threshold in [0,16,127,240]:
 mask=bytearray(v>threshold for v in a); comps=[]
 for i in range(len(mask)):
  if not mask[i]:continue
  mask[i]=0;q=deque([i]);n=0;x0=W;y0=H;x1=y1=0
  while q:
   k=q.popleft();y,x=divmod(k,W);n+=1;x0=min(x0,x);x1=max(x1,x);y0=min(y0,y);y1=max(y1,y)
   for j in (k-1 if x else -1,k+1 if x<W-1 else -1,k-W,k+W):
    if 0<=j<len(mask) and mask[j]:mask[j]=0;q.append(j)
  if n>100:comps.append((n,(x0,y0,x1+1,y1+1)))
 print('threshold',threshold,'count',len(comps),'largest',sorted(comps,reverse=True)[:35])
